public boolean sendHeartbeat() {
    if (!isPaired()) {
        return false;
    }
    String string = this.prefs.getString("device_id", null);
    String str = getBaseUrl() + "/api/v1/pollers/android/heartbeat";
    try {
        JSONObject jSONObject = new JSONObject();
        jSONObject.put("deviceId", string);
        jSONObject.put("timestamp", System.currentTimeMillis());
        jSONObject.put("batteryPercent", 100);
        jSONObject.put("isCharging", true);
        return postJson(str, jSONObject.toString(), string, null, null) != null;
    } catch (Exception e) {
        Log.e(TAG, "Heartbeat error: " + e.getMessage());
        return false;
    }
}
